def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    if n == 1:
        return 2
    elif n == 2:
        return 3
    elif n == 3:
        return 5
    elif n == 4:
        return 13
    elif n == 5:
        return 89
    else:
        prime_fib_iterator = (num for num in range(4, n + 1) if is_prime(num))
        prime_fib_number = next(prime_fib_iterator, None)
        return prime_fib_number if prime_fib_number is not None else n

