def derivative(xs: list) -> list:
    if len(xs) == 1:
        return [0] * len(xs)
    else:
        result = []
        for i in range(1, len(xs)):
            result.append(xs[i] * i)
        result.append(xs[0] + sum(xs[2:] * (j + 1) for j in range(1, len(xs) - 1)))
        return result


# Example usage:
