def select_words(s, n):
    # Initialize a list to store the words containing exactly n consonants
    result = []

    # Iterate through each character in the string
    for i, char in enumerate(s):
        # If the current character is a consonant, check the next character
        if 'a' <= char <= 'z' and 'A' <= char <= 'Z':
            # If the next character is a consonant too, add the current word to the result list
            if i + 1 < len(s) and 'a' <= s[i+1] <= 'z' and 'A' <= s[i+1] <= 'Z':
                result.append(s[i+1])
            # If the current character is not a consonant, return the current list
            elif not ('a' <= char <= 'z' and 'A' <= char <= 'Z'):
                return result
            # If the current character is not a consonant or the next character is not a consonant, break the loop
            else:
                break

    return result
