def tri(n):
    if n == 1:
        return [3]
    elif n == 2:
        return [1, 3]

    # Initialize the list with the first two elements
    tribonacci = [1, 3]

    # Compute the next values in the sequence for odd and even indices
    for i in range(2, n + 1):
        if i % 2 == 0:
            tribonacci.append(tribonacci[-1] + tribonacci[-2])
        else:
            tribonacci.append(tribonacci[-1] + tribonacci[-2] + tribonacci[-3])

    return tribonacci[:n + 1]

# Example usage
print(tri(3))  # Output: [1, 3, 2, 8]
print(tri(4))  # Output: [1, 3, 2, 8]
