def specialFilter(nums):
    """Return the count of elements greater than 10 with both first and last digits odd."""
    def is_first_last_odd(n):
        return str(n).lstrip('0')[-1:] in ['1', '3', '5', '7', '9']

    count = 0
    for n in nums:
        if n > 10 and is_first_last_odd(n):
            count += 1
    return count
