def int_to_mini_roman(number):
    # Define the mapping of integers to their roman numerals
    romans = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd',
        100: 'c', 90: 'xc', 50: 'l', 40: 'xl',
        10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'
    }

    # Convert the number to a string and ensure it's lowercase
    number = str(number)

    # Initialize the result string
    result = ""

    # Iterate over the mapping to build the result string
    for value, roman in romans.items():
        while number.startswith(value):
            result += roman
            number = number[len(value):]

    # Return the result in lowercase
    return result.lower()
