def do_algebra(operator, operand):
    if len(operand) == 0:
        return None

    # Check if all elements in the operand list are non-negative integers
    if not all(num >= 0 for num in operand):
        return None

    result = operand[0]
    for i in range(1, len(operand)):
        result = operator[operand[i-1]](result, operand[i])

    return result
